using System.Numerics;
using EnbNext.Assets;
using X87 = EnbNext.Rendering.EnbRetailExtendedX87Register;

namespace EnbNext.Rendering;

/// <summary>
/// One point-star generated by the current retail five-dimensional QMC path.
/// The fourth QMC coordinate is an index into PointGroup's 256 rotated
/// triangle table, not brightness. The fifth selects the authored atlas cell.
/// </summary>
public readonly record struct EnbRetailGeneratedPointStar(
    Vector3 Position,
    float Size,
    byte OrientationIndex,
    byte AtlasCell);

public readonly record struct EnbRetailPointTriangle(
    Vector2 Vertex0,
    Vector2 Vertex1,
    Vector2 Vertex2,
    Vector2 TexCoord0,
    Vector2 TexCoord1,
    Vector2 TexCoord2);

/// <summary>
/// Current-retail point-star generation and PointGroup geometry semantics used
///with the distinct four-corner geometry for the
/// quad-star branch.
/// </summary>
public static class EnbRetailStarPointSemantics
{
    private const float StarRadius = 100f;
    // 009576ED reads 00B11D34 (0x3F5DB22D), the authored 0.866f.
    private const float TriangleAtlasHeight = 0.866f;
    private const float FullTurn = MathF.PI * 2f;

    private static readonly int[] QmcBases = [2, 3, 5, 7, 11];

    public static IReadOnlyList<EnbRetailGeneratedPointStar> GenerateVisiblePrefix(
        EnbRetailStarLayerDefinition layer,
        int visibleStarCount)
    {
        ArgumentNullException.ThrowIfNull(layer);
        ValidatePointLayer(layer);
        if (visibleStarCount < 0 || visibleStarCount > layer.NumStars)
            throw new ArgumentOutOfRangeException(nameof(visibleStarCount));

        using var arithmetic = new EnbRetailLineArithmetic.Scope(EnbRetailLinePrecision.Single24);
        var stars = new EnbRetailGeneratedPointStar[visibleStarCount];
        int cellCount = 1 << checked(layer.TextureLog2Width * 2);
        for (int index = 0; index < visibleStarCount; index++)
        {
            int qmcIndex = checked(layer.QmcOffset + index);
            float q0 = RadicalInverse(qmcIndex, QmcBases[0]);
            float q1 = RadicalInverse(qmcIndex, QmcBases[1]);
            float q2 = RadicalInverse(qmcIndex, QmcBases[2]);
            float q3 = RadicalInverse(qmcIndex, QmcBases[3]);
            float q4 = RadicalInverse(qmcIndex, QmcBases[4]);

            float theta = FullTurn * q0;
            // 00482399/3E6 spills theta, but FSIN/FCOS retain extended
            // results until the subsequent PC24 multiply (not a float sine).
            X87 sine = X87.Sine(theta), cosine = X87.Cosine(theta);
            Vector3 direction;
            if (layer.Hemisphere)
            {
                float radial = RadialPower(1f - (q1 * q1));
                direction = new Vector3(
                    (float)(cosine * radial),
                    (float)(sine * radial),
                    q1);
            }
            else
            {
                float radial = RadialPower(q1 * (1f - q1));
                direction = new Vector3(
                    (float)((cosine * radial) + (cosine * radial)),
                    (float)((sine * radial) + (sine * radial)),
                    1f - (2f * q1));
            }

            float size = layer.MinSize + (q2 * (layer.MaxSize - layer.MinSize));
            byte orientation = unchecked((byte)TruncateLikeRetail(q3 * 255f));
            int atlasIndex = layer.PickRandomly
                ? TruncateLikeRetail(q4 * cellCount)
                : index;
            byte atlasCell = unchecked((byte)(atlasIndex & (cellCount - 1)));

            stars[index] = new EnbRetailGeneratedPointStar(
                direction * StarRadius,
                size,
                orientation,
                atlasCell);
        }

        return stars;
    }

    public static EnbRetailPointTriangle BuildTriangle(
        float size,
        byte orientationIndex,
        byte atlasCell,
        int textureLog2Width)
    {
        if (!float.IsFinite(size) || size < 0f)
            throw new ArgumentOutOfRangeException(nameof(size));
        if (textureLog2Width < 0 || textureLog2Width > 4)
            throw new ArgumentOutOfRangeException(nameof(textureLog2Width));

        // Same 00957370 tables as particle PointGroup; initialized after device
        // creation under PC24, including the retained angle's per-step rounding.
        Vector2 Corner(int corner)
        {
            Vector3 offset = EnbRetailPointGroupExpansion.Expand(
                Vector3.Zero, size, 0, orientationIndex, corner);
            return new(offset.X, offset.Y);
        }
        Vector2 v0 = Corner(0), v1 = Corner(1), v2 = Corner(2);

        int width = 1 << textureLog2Width;
        int cellCount = width * width;
        int cell = atlasCell & (cellCount - 1);
        int row = cell / width;
        int column = cell - (row * width);
        float cellSize = 1f / width;
        float u = column * cellSize;
        float v = row * cellSize;

        return new EnbRetailPointTriangle(
            v0,
            v1,
            v2,
            new Vector2(u + (0.5f * cellSize), v),
            new Vector2(u, v + (TriangleAtlasHeight * cellSize)),
            new Vector2(u + cellSize, v + (TriangleAtlasHeight * cellSize)));
    }

    /// <summary>00957370 quad table and index order; 00955FE0 scales its
    /// four rotated corners by the same generated size used by point stars.</summary>
    public static IReadOnlyList<(Vector2 Position, Vector2 TexCoord)> BuildQuad(
        float size, byte orientationIndex, byte atlasCell, int textureLog2Width)
    {
        if (!float.IsFinite(size) || size < 0f) throw new ArgumentOutOfRangeException(nameof(size));
        if (textureLog2Width < 0 || textureLog2Width > 4)
            throw new ArgumentOutOfRangeException(nameof(textureLog2Width));
        Vector2 Corner(int corner)
        {
            Vector3 offset = EnbRetailPointGroupExpansion.Expand(
                Vector3.Zero, size, 1, orientationIndex, corner);
            return new(offset.X, offset.Y);
        }
        int width = 1 << textureLog2Width;
        int cell = atlasCell & (width * width - 1);
        float step = 1f / width, u = (cell % width) * step, v = (cell / width) * step;
        (Vector2, Vector2)[] corners =
        [
            (Corner(0), new(u, v)),
            (Corner(1), new(u, v + step)),
            (Corner(2), new(u + step, v + step)),
            (Corner(3), new(u + step, v)),
        ];
        return [corners[0], corners[1], corners[2], corners[2], corners[3], corners[0]];
    }
    public static float RadicalInverse(int index, int primeBase)
    {
        if (index < 0)
            throw new ArgumentOutOfRangeException(nameof(index));
        if (primeBase < 2)
            throw new ArgumentOutOfRangeException(nameof(primeBase));

        float result = 0f;
        float factor = 1f / primeBase;
        int value = index;
        while (value != 0)
        {
            result += (value % primeBase) * factor;
            value /= primeBase;
            factor /= primeBase;
        }

        return result;
    }

    // 00482382/3C7 call A27C90 with exponent 0.5. For these nonnegative,
    // bounded QMC inputs the CRT takes A27CFF FYL2X -> A30F60 exponentiation,
    // retaining PC24 (A30F75), not FSQRT. Zero takes A27E34's FLDZ branch.
    private static float RadialPower(float value)
    {
        if (value == 0f) return 0f;
        const ushort control = 0x007f;
        X87 logarithm = X87.EvaluateControlled(34, value, 0.5, control);
        X87 integer = X87.EvaluateControlled(28, logarithm, default, control);
        X87 fraction = -(integer - logarithm);
        X87 power = X87.EvaluateControlled(35, fraction, default, control) + (X87)1;
        return (float)X87.EvaluateControlled(22, power, integer, control);
    }

    private static void ValidatePointLayer(EnbRetailStarLayerDefinition layer)
    {

        if (layer.NumStars < 0)
            throw new ArgumentOutOfRangeException(nameof(layer), "NumStars must be non-negative.");
        if (!float.IsFinite(layer.MinSize) || !float.IsFinite(layer.MaxSize) || layer.MinSize < 0f || layer.MaxSize < layer.MinSize)
            throw new ArgumentOutOfRangeException(nameof(layer), "Star size range is invalid.");
        if (layer.QmcOffset < 0)
            throw new ArgumentOutOfRangeException(nameof(layer), "R6Y requires a non-negative current-retail QMCOffset.");
        if (layer.TextureLog2Width < 0 || layer.TextureLog2Width > 4)
            throw new ArgumentOutOfRangeException(nameof(layer), "PointGroup clamps TextureLog2Width to the current-retail 0..4 table range.");
    }

    // 00482446/00482462 call 00A264EC, which sets RC=truncate before FISTP.
    private static int TruncateLikeRetail(float value)
        => checked((int)value);
}
